csui.define('dctmw/commands/open',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'csui/models/command',
  'csui/models/commands',
  'i18n!dctmw/commands/nls/lang',
  'dctm-ext!dctmw/commands/open.delegates'
], function(_, $, CommandModel, CommandCollection, lang, extOpenDelegates){
  'use strict';
  
  const delegates = new CommandCollection();
  if(extOpenDelegates) {
    delegates.add(
      _.chain(extOpenDelegates)
        .flatten(true)
        .map(Command => new Command())
        .value()
    );
  }
  
  const CMDOpen = CommandModel.extend({
    defaults: {
      signature: 'D4-Open',
      command_key: ['default', 'open', 'D4-Open'],
      name: lang.CommandNameOpen,
      scope: 'single'
    },
    
    enabled(status, options) {
      let retVal = CommandModel.prototype.enabled.call(this, status, options);
      
      if(retVal) {
        retVal = delegates.any(d => d.enabled(status, options));
      }
      
      return retVal;
    },
    
    execute(status, options) {
      const delegate = delegates.find(d => d.enabled(status, options));
      if(delegate) {
        return delegate.execute(status, options);
      }
      return $.Deferred().reject('No appropriate delegate').promise();
    }
  });
  
  return CMDOpen;
});

csui.define('dctmw/commands/refresh.list',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'csui/models/command',
  'smart/controls/globalmessage/globalmessage',
  'smart/dialogs/modal.alert/modal.alert',
  'dctmw/utils/utils',
  'i18n!dctmw/commands/nls/lang'
], function (_, $, CommandModel, GlobalMessage, ModalAlert, utils, lang) {
  'use strict';

  const RefreshList = CommandModel.extend({
    defaults: {
      signature: 'D4-RefreshList',
      name: lang.CommandNameRefreshList,
      scope: 'single'
    },

    execute: function (status, options) {
      const deferred = $.Deferred();
      if (status.toolItem && status.toolItem.get('suppressFailMessage')) {
        status.suppressFailMessage = true;
      }
      
      this._confirmRefresh(status)
        .then(()=>{
          status.originatingView && status.originatingView.trigger('before:refresh:list:data');
          status.collection.fetch(_.extend({}, options, {'reload': true, skipSWCache: true})).done(function () {
            status.originatingView && status.originatingView.trigger('refresh:list:data');
            deferred.resolve();
          }).fail(function (error) {
            if (status.suppressFailMessage !== true) {
              let msg = error.message || error;
              if (error && error.responseText) {
                msg = utils.parseAjaxErrorAsString(error);
              }
              if (msg) {
                GlobalMessage.showMessage('error', msg);
              }
            }
            deferred.reject();
          });
        }, deferred.resolve);
      
      return deferred.promise();
    },
    
    _confirmRefresh: function(status={}) {
      const dfd = $.Deferred();
      
      const collection = status.collection;
      if(!collection || !_.isFunction(collection.isStateDirty) || !collection.isStateDirty()) {
        dfd.resolve();
      } else {
        ModalAlert.confirmQuestion(lang.RefreshConfirmationMessage, lang.RefreshConfirmationAlertTitle, {
          buttons: {
            showYes: true,
            showNo: false,
            showCancel: true,
            labelYes: lang.RefreshConfirmationButtonLabel
          }
        }).always(answer => {
          answer === true ? dfd.resolve() : dfd.reject();
        });
      }
      
      return dfd.promise();
    }
  });
  return RefreshList;
});


