  defWidgetMap[widgetConstants.DEFAULT.TASKS] = {type: widgetConstants.D2.TASKS};
  defWidgetMap[widgetConstants.DEFAULT.TASK_ATTACHMENTS] = {type: widgetConstants.D2.TASK_ATTACHMENTS};
  defWidgetMap[widgetConstants.DEFAULT.MY_WORKFLOWS] = {type: widgetConstants.D2.WORKFLOWS};
  defWidgetMap[widgetConstants.DEFAULT.ALL_WORKFLOWS] = {type: widgetConstants.D2.WORKFLOWS};
  defWidgetMap[widgetConstants.DEFAULT.BRAVAENTERPRISE] = {type: widgetConstants.D2.BRAVAENTERPRISE};
  defWidgetMap[widgetConstants.DEFAULT.BRAVAIV] = {type: widgetConstants.D2.BRAVAIV};

