csui.define('dctmw/utils/user.utils',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'csui/utils/contexts/factories/connector',
  'csui/utils/contexts/factories/member',
  'dctmw/lib/uri-templates',
  'dctmw/utils/authenticators/session'
], function ($, _, ConnectorFactory, MemberModelFactory, UriTemplates, Session) {
  'use strict';


  var userAvatarBlobData = {};

  return {

    getUserProfileRepositoryLink: function () {
      throw new Error(`Override this method to return the API uri for getting user profile image`);
    },

    getUserPhotoUrl: function (userName) {
      return this.getUserProfileImageUrl(userName);
    },

    getUserProfileImageUrl: function (userName) {
      var templateUrl = this.getUserProfileRepositoryLink();
      if (templateUrl) {
        var templateParams = {
          'user-name': userName
        },
          template = new UriTemplates(templateUrl);
        return template.fill(templateParams);
      }
    },


    getMemberModelForUser: function (userId) {
      var memberModel = Session.get().getContext().getModel(MemberModelFactory, {
        attributes: { id: userId },
        options: {
          connector: Session.get().getContext().getObject(ConnectorFactory)
        },
        temporary: true
      }
      );
      return memberModel;
    },

    getUserAvatarBlobUrl: function (options) {
      options = options || {};

      if (!options.userId) {
        throw Error('User id is mandatory for resolving user avatar.')
      }

      if (!options.url) {
        throw Error('Photo URL is mandatory for resolving user avatar.')
      }

      var me = this,
        dfd = $.Deferred(),
        connector = Session.get().getContext().getObject(ConnectorFactory),
        userId = options.userId,
        cachedAvatarBlobUrl = userAvatarBlobData[userId];

      if (cachedAvatarBlobUrl) {
        if (cachedAvatarBlobUrl === 'NOT_FOUND') {
          dfd.reject();
        } else {
          dfd.resolve(cachedAvatarBlobUrl);
        }
      } else {
        var url = options.url;
        $.ajax(connector.extendAjaxOptions({
          url: url,
          dataType: 'binary',
          success: function (response) {
            let avatarBlobContentUrl = URL.createObjectURL(response);
            userAvatarBlobData[userId] = avatarBlobContentUrl;
            dfd.resolve(avatarBlobContentUrl);
          },
          error: function (xhr) {
            if (xhr.status === 404) {
              userAvatarBlobData[userId] = 'NOT_FOUND';
            } else {
              me.clearUserAvatarBlobUrl(userId);
            }
            dfd.reject();
          }
        }));
      }
      return dfd.promise();
    },

    clearUserAvatarBlobUrl: function (userId) {
      delete userAvatarBlobData[userId];
    }

  };
});

csui.define('dctmw/widgets/user.avatar/user.avatar.view',["nuc/lib/marionette", "dctmw/utils/user.utils"], function (_nucLibMarionette, userUtils) {
  let ItemView = _nucLibMarionette.ItemView;
  class UserAvatarView extends ItemView {
    constructor(options = {}) {
      if (!options.model && options.userId) {
        options.model = userUtils.getMemberModelForUser(options.userId);
      }
      if (!options.model) {
        throw Error("Member model is mandatory.");
      }
      super(options);
      this.#setAttributeForAvatar();
    }
    #setAttributeForAvatar() {
      let initials = this.#resolveInitial();
      this.$el.attr("initials", initials);
      if (this.options.size) {
        this.$el.attr("size", this.options.size);
      }
    }
    onRender() {
      this.#resolvePhoto();
    }
    #resolveInitial() {
      return this.model.get("initials") || this.model.get("id").substring(0, 1).toUpperCase();
    }
    #resolvePhoto() {
      let photoUrl = this.#getPhotoUrl();
      if (photoUrl) {
        userUtils.getUserAvatarBlobUrl({
          userId: this.model.get("id"),
          url: photoUrl
        }).done(avatarBlobUrl => {
          this.$el.attr("image", avatarBlobUrl);
          this.trigger("user:avatar:ready", true);
        }).fail(() => {
          this.$el.removeAttr("image");
          this.trigger("user:avatar:ready", false);
        });
      }
    }
    #getPhotoUrl() {
      let photoUrl = this.options.photoUrl;
      if (!photoUrl && this.options.resolvePhoto === true) {
        photoUrl = userUtils.getUserPhotoUrl(this.model.get("id"));
      }
      return photoUrl;
    }
  }
  Object.assign(UserAvatarView.prototype, {
    className: "dctm-user-avatar",
    template: false,
    tagName: "otc-avatar"
  });
  Object.defineProperty(UserAvatarView.prototype.constructor, "name", {
    value: "UserAvatarView"
  });
  return UserAvatarView;
});


